#include "config.h"

#include "@INCLUDE@"

int
LLVMFuzzerTestOneInput(const guint8 *data, gsize size)
{
        g_autoptr(FuFirmware) firmware = FU_FIRMWARE(@FIRMWARENEW@);
        g_autoptr(GBytes) fw = g_bytes_new(data, size);
        gboolean ret;

        (void)g_setenv("G_DEBUG", "fatal-criticals", TRUE);
        (void)g_setenv("FWUPD_FUZZER_RUNNING", "1", TRUE);
        ret = fu_firmware_parse(firmware, fw, FWUPD_INSTALL_FLAG_NONE, NULL);
        if (!ret && fu_firmware_has_flag(firmware, FU_FIRMWARE_FLAG_HAS_CHECKSUM)) {
                g_clear_object(&firmware);
                firmware = FU_FIRMWARE(@FIRMWARENEW@);
                ret = fu_firmware_parse(firmware,
                                        fw,
                                        FWUPD_INSTALL_FLAG_NO_SEARCH |
                                            FWUPD_INSTALL_FLAG_IGNORE_VID_PID |
                                            FWUPD_INSTALL_FLAG_IGNORE_CHECKSUM,
                                        NULL);
        }
        if (ret) {
                g_autoptr(GBytes) fw2 = fu_firmware_write(firmware, NULL);
        }
        return 0;
}
/*
 * Copyright 2020 Richard Hughes <richard@hughsie.com>
 *
 * SPDX-License-Identifier: LGPL-2.1-or-later
 */

#include <glib.h>

__attribute__((weak)) extern int
LLVMFuzzerTestOneInput(const unsigned char *data, size_t size);
__attribute__((weak)) extern int
LLVMFuzzerInitialize(int *argc, char ***argv);

int
main(int argc, char **argv)
{
        g_assert_nonnull(LLVMFuzzerTestOneInput);
        if (LLVMFuzzerInitialize != NULL)
                LLVMFuzzerInitialize(&argc, &argv);

        for (int i = 1; i < argc; i++) {
                gsize bufsz = 0;
                g_autofree gchar *buf = NULL;
                g_autoptr(GError) error = NULL;
                g_printerr("Running: %s\n", argv[i]);
                if (!g_file_get_contents(argv[i], &buf, &bufsz, &error)) {
                        g_printerr("Failed to load: %s\n", error->message);
                        continue;
                }
                LLVMFuzzerTestOneInput((const guint8 *)buf, bufsz);
                g_printerr("Done\n");
        }
        return EXIT_SUCCESS;
}
